content:
{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "هوذا، تكلم في أذني شعبي بكلمات النبوة التي سأضعها في فمك، يقول الرب.",
      "chapter": 15,
      "verse": 1
    },
    {
      "text_ar": "اجعلها مكتوبة على ورق، لأنها أمينة وصادقة.",
      "chapter": 15,
      "verse": 2
    },
    {
      "text_ar": "لا تخف من مؤامراتهم ضدك. ولا تدع عدم إيمان المتحدثين ضدك يزعجك.",
      "chapter": 15,
      "verse": 3
    },
    {
      "text_ar": "لأن جميع غير المؤمنين سيموتون في عدم إيمانهم.",
      "chapter": 15,
      "verse": 4
    },
    {
      "text_ar": "هوذا، يقول الرب، أنا جالب شروراً على الأرض كلها: سيفاً، جوعاً، موتاً، ودماراً.",
      "chapter": 15,
      "verse": 5
    },
    {
      "text_ar": "لأن الشر قد طغى على كل أرض، وأعمالهم المؤذية قد بلغت نهايتها.",
      "chapter": 15,
      "verse": 6
    },
    {
      "text_ar": "لذلك، يقول الرب،",
      "chapter": 15,
      "verse": 7
    },
    {
      "text_ar": "لن أصمت بعد عن شرهم الذي يرتكبونه باستهانة، ولن أتحملهم في هذه الأمور التي يمارسونها بشر. هوذا، الدم البريء والصديق يصرخ إليّ، ونفوس الأبرار تصرخ باستمرار.",
      "chapter": 15,
      "verse": 8
    },
    {
      "text_ar": "سأنتقم لهم حقاً، يقول الرب، وسأقبل إليّ كل الدم البريء من بينهم.",
      "chapter": 15,
      "verse": 9
    },
    {
      "text_ar": "هوذا، شعبي يُقاد كقطيع إلى الذبح. لن أسمح لهم الآن بالسكن في أرض مصر،",
      "chapter": 15,
      "verse": 10
    },
    {
      "text_ar": "بل سأخرجهم بيد قديرة وذراع رفيعة، وأضرب مصر بالضربات كما في السابق، وأبيد كل أرضها.",
      "chapter": 15,
      "verse": 11
    },
    {
      "text_ar": "لتنوح مصر وأساساتها، بسبب ضربة التأديب والعقاب الذي سيجلبه الله عليها.",
      "chapter": 15,
      "verse": 12
    },
    {
      "text_ar": "لينوح المزارعون الذين يفلحون الأرض، لأن بذورهم ستفشل وأشجارهم ستتخرب بسبب اللفحة والبَرَد والعاصفة الرهيبة.",
      "chapter": 15,
      "verse": 13
    },
    {
      "text_ar": "ويل للعالم وللساكنين فيه!",
      "chapter": 15,
      "verse": 14
    },
    {
      "text_ar": "لأن السيف ودمارهم يقتربان، وأمة ستقوم على أمة للقتال وبأيديهم أسلحة.",
      "chapter": 15,
      "verse": 15
    },
    {
      "text_ar": "لأن فتنة ستحدث بين الناس، وسيتقوون بعضهم على بعض. في جبروتهم، لن يحترموا ملكهم ولا رئيس عظماءهم.",
      "chapter": 15,
      "verse": 16
    },
    {
      "text_ar": "لأن الرجل سيشتهي أن يدخل مدينة ولن يستطيع.",
      "chapter": 15,
      "verse": 17
    },
    {
      "text_ar": "لأنه بسبب كبريائهم ستضطرب المدن، وستتهدم البيوت، وسيخاف الرجال.",
      "chapter": 15,
      "verse": 18
    },
    {
      "text_ar": "لن يشفق الرجل على جيرانه، بل سيهاجم بيوتهم بالسيف وينهب ممتلكاتهم، بسبب نقص الخبز والضيق الشديد.",
      "chapter": 15,
      "verse": 19
    },
    {
      "text_ar": "هوذا، يقول الله، أجمع معاً كل ملوك الأرض لأثير أولئك الذين هم من مشرق الشمس، ومن الجنوب، ومن الشرق، ولبنان، لكي يرتد بعضهم على بعض، ويجازوا ما فعلوه بهم.",
      "chapter": 15,
      "verse": 20
    }
  ]
}
